import backtrader as bt


class ADXROCBreakoutStrategy(bt.Strategy):
    def __init__(self):
        self.adx = bt.indicators.AverageDirectionalMovementIndex(self.data, period=14)
        self.adx_roc = bt.indicators.RateOfChange(self.adx, period=20)
        self.roc_sma = bt.indicators.SimpleMovingAverage(self.adx_roc, period=20)
        self.roc_std = bt.indicators.StandardDeviation(self.adx_roc, period=20)
        self.roc_cross = bt.indicators.CrossOver(self.adx_roc, self.roc_sma)
        self.order = None
        self.stop_order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.adx_roc[0] > self.roc_sma[0] + 2.0 * self.roc_std[0]:
                self.order = self.buy()
            elif self.adx_roc[0] < self.roc_sma[0] - 2.0 * self.roc_std[0]:
                self.order = self.sell()
        elif self.position.size > 0 and self.roc_cross[0] < 0:
            if self.stop_order:
                self.cancel(self.stop_order)
            self.order = self.close()
        elif self.position.size < 0 and self.roc_cross[0] > 0:
            if self.stop_order:
                self.cancel(self.stop_order)
            self.order = self.close()

    def notify_order(self, order):
        if order.status == order.Completed:
            if order is self.order:
                if self.position.size > 0:
                    self.stop_order = self.sell(
                        exectype=bt.Order.Stop,
                        price=order.executed.price * 0.98,
                    )
                elif self.position.size < 0:
                    self.stop_order = self.buy(
                        exectype=bt.Order.Stop,
                        price=order.executed.price * 1.02,
                    )
                self.order = None
            elif order is self.stop_order:
                self.stop_order = None
        elif order.status in [order.Canceled, order.Margin, order.Rejected]:
            if order is self.order:
                self.order = None
            if order is self.stop_order:
                self.stop_order = None
